import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/sheets/overview-toolbar.png",f=JSON.parse('{"title":"Sheets","description":"Sheets is a spreadsheet for formulas, charts, and live data that your team edits together.","frontmatter":{"title":"Sheets","description":"Sheets is a spreadsheet for formulas, charts, and live data that your team edits together.","type":"overview"},"headers":[],"relativePath":"sheets/index.md","filePath":"sheets/index.md"}'),l={name:"sheets/index.md"};function i(n,e,h,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="sheets" tabindex="-1">Sheets <a class="header-anchor" href="#sheets" aria-label="Permalink to &quot;Sheets&quot;">​</a></h1><p>Sheets is a spreadsheet for formulas, charts, and live data that your team edits together.</p><p>Use it to:</p><ul><li>Track a budget, a task list, or an invoice with formulas that update as you type</li><li>Summarize data with charts and pivot tables</li><li>Query a database or read a lakehouse table into a tab</li></ul><p><img src="'+r+'" alt="The Sheets editor with its toolbar, Name box, formula bar, and tab bar labeled"></p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong> and select <strong>New sheet</strong>. A sheet named <strong>New Sheet</strong> opens with one tab, <strong>Sheet1</strong>.</li><li>Click a cell and type a value or a formula such as <code>=SUM(B2:B7)</code>, then press <code>Enter</code>. See <a href="/docs/sheets/formulas.html">Formulas</a>.</li><li>Click <strong>Share</strong> in the top right to invite your team. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>To learn the basics in one sitting, follow <a href="/docs/sheets/build-a-budget.html">Build a budget</a>.</p><h2 id="enter-and-organize-data" tabindex="-1">Enter and organize data <a class="header-anchor" href="#enter-and-organize-data" aria-label="Permalink to &quot;Enter and organize data&quot;">​</a></h2><ul><li><a href="/docs/sheets/edit-and-format.html">Edit and format cells</a>: type and fill data, find values, and set number formats, colors, borders, and alignment</li><li><a href="/docs/sheets/rows-columns-tabs.html">Rows, columns, and tabs</a>: insert, hide, freeze, and resize rows and columns, and manage tabs</li><li><a href="/docs/sheets/sort-and-filter.html">Sort and filter</a>: sort a table by a column and show only the rows you need</li></ul><h2 id="calculate" tabindex="-1">Calculate <a class="header-anchor" href="#calculate" aria-label="Permalink to &quot;Calculate&quot;">​</a></h2><ul><li><a href="/docs/sheets/formulas.html">Formulas</a>: enter formulas, reference other cells and tabs, and find a function</li><li><a href="/docs/sheets/functions.html">Function reference</a>: every function, with its syntax</li></ul><h2 id="visualize-and-summarize" tabindex="-1">Visualize and summarize <a class="header-anchor" href="#visualize-and-summarize" aria-label="Permalink to &quot;Visualize and summarize&quot;">​</a></h2><ul><li><a href="/docs/sheets/charts.html">Charts</a>: turn a range into a chart</li><li><a href="/docs/sheets/pivot-tables.html">Pivot tables</a>: summarize a table by rows, columns, and values</li></ul><h2 id="control-input-and-highlight" tabindex="-1">Control input and highlight <a class="header-anchor" href="#control-input-and-highlight" aria-label="Permalink to &quot;Control input and highlight&quot;">​</a></h2><ul><li><a href="/docs/sheets/data-validation.html">Data validation</a>: add checkboxes, dropdown lists, and input rules</li><li><a href="/docs/sheets/conditional-formatting.html">Conditional formatting</a>: color cells that match a rule</li></ul><h2 id="connect-live-data" tabindex="-1">Connect live data <a class="header-anchor" href="#connect-live-data" aria-label="Permalink to &quot;Connect live data&quot;">​</a></h2><ul><li><a href="/docs/sheets/connect-a-database.html">Connect a database</a>: run a SQL query into a tab</li><li><a href="/docs/sheets/lakehouse.html">Lakehouse tables</a>: read an Iceberg or Delta table into a tab</li></ul><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>You can view and edit a sheet on a phone. Double-tap a cell to edit it in a panel at the bottom of the screen, pinch to zoom, and touch and hold a cell for its menu. Tools that don&#39;t fit the toolbar, such as number formats, borders, and charts, are in the ⋮ (<strong>More formatting options</strong>) menu. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a></li><li><a href="/docs/sheets/functions.html">Function reference</a></li><li><a href="/docs/files/import-export.html">Import and export files</a> for <code>.xlsx</code> and <code>.csv</code></li><li><a href="/docs/collaborate/comments.html">Comments</a> and <a href="/docs/collaborate/version-history.html">version history</a></li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/sheets/build-a-budget.html">Build a budget</a> to practice formulas and formatting in about 10 minutes.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to invite collaborators.</li><li><a href="/docs/collaborate/templates.html">Start from a template</a> instead of a blank sheet.</li></ul>',24)])])}const b=a(l,[["render",i]]);export{f as __pageData,b as default};
